const orderStep=o=>{const provider=o.providerId===state.user.id,closed=['completed','cancelled','declined'].includes(o.status);if(closed)return {group:'closed',label:'Ver histórico'};if(o.reschedule)return o.reschedule.from===state.user.id?{group:'waiting',label:'Aguardando resposta sobre horário'}:{group:'action',label:'Responder novo horário'};if(o.status==='new')return provider?{group:'action',label:'Responder pedido'}:{group:'waiting',label:'Aguardando proposta'};if(o.status==='awaiting_final_quote')return provider?{group:'action',label:'Enviar orçamento final'}:{group:'waiting',label:'Aguardando orçamento final'};if(o.status==='awaiting_buyer')return provider?{group:'waiting',label:'Aguardando resposta do cliente'}:{group:'action',label:'Responder pergunta'};if(o.status==='quoted')return provider?{group:'waiting',label:'Aguardando resposta do cliente'}:{group:'action',label:'Avaliar proposta'};if(o.status==='confirmed')return provider?o.booking&&Date.parse(o.booking.start)>Date.now()?{group:'progress',label:'Atendimento agendado'}:{group:'action',label:'Iniciar ou concluir serviço'}:{group:'progress',label:o.booking?'Atendimento agendado':'Serviço confirmado'};if(o.status==='in_progress')return provider?{group:'progress',label:'Marcar realizado ao terminar'}:{group:'progress',label:'Serviço em execução'};if(o.status==='awaiting_confirmation')return provider?{group:'waiting',label:'Aguardando confirmação do cliente'}:{group:'action',label:'Confirmar conclusão'};if(o.status==='disputed')return provider?{group:'progress',label:'Conversar sobre o problema'}:{group:'action',label:'Registrar solução'};return {group:'progress',label:'Acompanhar pedido'}};
