async function pageService(id){const s=(await api('/api/services/'+id)).service,own=s.isOwner;show(back('/servicos')+`<div class="two-col"><div class="stack"><div class="detail-media">${s.media?.length?mediaTile(s.media[0]):'<span class="placeholder">✦</span>'}</div>${s.media?.length>1?`<div class="gallery">${s.media.slice(1).map(mediaTile).join('')}</div>`:''}<div class="panel"><p class="eyebrow">${esc(s.category)}</p><h1>${esc(s.service)}</h1><p class="muted">${esc(s.neighborhood)} · ${esc(serviceModes(s).map(x=>modeNames[x]||x).join(' · '))}</p><p class="detail-text">${esc(s.description)}</p><p><strong>${esc(s.price||'Preço sob orçamento')}</strong></p></div><div class="panel"><h2>Avaliações</h2><p>${s.rating.count?`★ ${s.rating.average} · ${s.rating.count} avaliações`:'Ainda sem avaliações'}</p></div></div><div class="stack"><div class="panel"><a href="/perfil/${s.provider.id}" class="profile-row"><span class="avatar">${avatar(s.provider)}</span><span><strong>${esc(s.provider.name)}</strong><small>Ver perfil →</small></span></a><div class="stat-row"><span class="pill ${s.availability==='ready'?'ready':''}">${esc(s.availability==='ready'?'Disponível agora':s.availability==='open'?'Aberto agora':s.availability==='busy'?'Ocupado agora':s.availability==='closed'?'Fechado agora':'Consultar horário')}</span></div>${own?`<a class="button primary" href="/anunciar/${s.id}">Editar anúncio</a>`:`<div class="stack"><a class="button primary" href="/solicitar/${s.id}">Solicitar serviço</a><button class="button secondary" data-action="start-chat" data-target="${s.provider.id}" data-service="${s.id}">Conversar</button></div>`}</div><a class="button ghost small" href="/denunciar?tipo=service&id=${s.id}">Denunciar anúncio</a><div class="panel"><h3>Atendimento</h3><p>${esc(s.areas?.length?s.areas.join(', '):s.neighborhood)}</p><p class="muted">O valor e, quando necessário, o horário são combinados na proposta.</p></div></div></div>`)}
