 const groups=[['action','Precisa de você'],['waiting','Aguardando resposta'],['progress','Em andamento'],['closed','Encerrados']].map(([key,title])=>manageGroup(title,rows.filter(o=>orderStep(o).group===key).map(orderRow))).join('');
 const filter=serviceId?`<div class="filter-note">Pedidos deste serviço <a href="/pedidos?lado=recebidos">Ver todos</a></div>`:'';
 show(heading(side==='recebidos'?'Pedidos recebidos':'Meus pedidos')+tabs+filter+(rows.length?groups:empty('Nenhum pedido',side==='recebidos'?'Quando alguém pedir seu serviço, aparecerá aqui.':'Encontre um serviço para enviar um pedido.','/servicos','Buscar serviço')));
