async function pageOrder(id){if(needLogin(location.pathname))return;const o=(await api('/api/orders/'+id)).order,provider=o.providerId===state.user.id,buyer=!provider,chat=await chatBlock(o.chatId),service=o.service,step=orderStep(o);let actions=step.group==='action'?'':`<p class="step-summary">${esc(step.group==='closed'?'Pedido encerrado.':step.label)}</p>`;
 if(provider&&['new','awaiting_final_quote'].includes(o.status)){actions+=`<h3>Enviar proposta</h3>`+orderForm(id,'quote',`<label>O que será feito<textarea name="scope" required minlength="10" placeholder="Descreva o combinado"></textarea></label><div class="form-grid"><label>Valor total<input name="price" required placeholder="Ex.: R$ 120"></label><label>Tipo<select name="kind"><option value="service">Serviço</option><option value="visit">Visita de avaliação</option></select></label></div><details class="optional-details"><summary>Agendar dia e horário (opcional)</summary><div class="optional-body"><div class="form-grid"><label>Início<input name="start" type="datetime-local"></label><label>Fim<input name="end" type="datetime-local"></label></div><small>Para visita, informe início e fim.</small></div></details>`,'Enviar proposta');if(o.status==='new')actions+=optionalAction('Pedir mais informações',orderForm(id,'ask','<label>Sua pergunta<input name="detail" required minlength="5" placeholder="O que precisa saber?"></label>','Enviar pergunta','secondary'))+optionalAction('Recusar pedido',orderForm(id,'decline','<label>Motivo<input name="detail" required minlength="3"></label>','Recusar','danger'))}
 if(buyer&&o.status==='awaiting_buyer')actions+=orderForm(id,'answer','<label>Resposta<textarea name="detail" required minlength="3"></textarea></label>','Responder');
 if(buyer&&o.status==='quoted')actions+=`<div class="panel"><h3>Proposta recebida</h3><p>${esc(o.quote.scope)}</p><p><strong>${esc(o.quote.price)}</strong> · ${o.quote.start?date(o.quote.start)+' até '+date(o.quote.end):'Sem horário marcado'}</p>${o.quote.kind==='visit'?'<p class="muted">A visita terá orçamento separado para o serviço.</p>':''}<button class="button primary" data-action="order-quick" data-id="${id}" data-value="accept">Aceitar proposta</button></div>`+optionalAction('Pedir ajuste',orderForm(id,'adjust','<label>O que deseja ajustar?<textarea name="detail" required minlength="5"></textarea></label>','Enviar ajuste','secondary'));

 if(provider&&o.status==='confirmed')actions+=`<button class="button primary" data-action="order-quick" data-id="${id}" data-value="start">Marcar como iniciado</button>`;
 if(provider&&['confirmed','in_progress'].includes(o.status))actions+=` <button class="button secondary" data-action="order-quick" data-id="${id}" data-value="done">Marcar como realizado</button>`;
 if(buyer&&o.status==='awaiting_confirmation')actions+=`<button class="button primary" data-action="order-quick" data-id="${id}" data-value="confirm">Confirmar conclusão</button>`;
 if(buyer&&['confirmed','in_progress','awaiting_confirmation'].includes(o.status))actions+=optionalAction('Informar problema',orderForm(id,'problem','<label>Conte o que aconteceu<textarea name="detail" required minlength="5"></textarea></label>','Enviar problema','secondary'));
 if(buyer&&o.status==='disputed')actions+=orderForm(id,'resolve','<label>Como foi resolvido?<textarea name="detail" required minlength="3"></textarea></label>','Registrar solução','secondary');
 if(buyer&&o.status==='completed'&&!o.reviewed)actions+=`<h3>Avaliar serviço</h3><form class="form" data-form="review" data-id="${id}"><label>Nota<select name="stars">${[5,4,3,2,1].map(x=>`<option value="${x}">${x} estrelas</option>`).join('')}</select></label><label>Como foi sua experiência?<textarea name="text" required minlength="10"></textarea></label><button class="button primary">Enviar avaliação</button></form>`;
 if(o.status==='confirmed'&&o.booking){if(o.reschedule&&o.reschedule.from!==state.user.id)actions+=`<div class="panel"><h3>Remarcação proposta</h3><p>${date(o.reschedule.start)} até ${date(o.reschedule.end)}</p><button class="button primary" data-action="order-quick" data-id="${id}" data-value="reschedule_accept">Aceitar horário</button> <button class="button secondary" data-action="order-quick" data-id="${id}" data-value="reschedule_decline">Recusar</button></div>`;else if(!o.reschedule)actions+=optionalAction('Pedir outro horário',orderForm(id,'reschedule','<div class="form-grid"><label>Início<input type="datetime-local" name="start" required></label><label>Fim<input type="datetime-local" name="end" required></label></div>','Propor remarcação','secondary'));else actions+='<p class="muted">Aguardando resposta sobre a remarcação.</p>'}
 if(!['completed','cancelled','declined','disputed'].includes(o.status)&&!(provider&&o.status==='new'))actions+=optionalAction('Cancelar pedido',orderForm(id,'cancel','<label>Motivo<input name="detail" required minlength="3"></label>','Confirmar cancelamento','danger'));
 show(back(provider?'/pedidos?lado=recebidos&servico='+o.listingId:'/pedidos?lado=feitos')+heading(service?.service||'Pedido',provider?`Pedido de ${o.buyer?.name}`:`Anunciante: ${o.provider?.name}`)+`<div class="two-col"><div class="stack"><div class="panel"><div class="page-head"><h2>Pedido</h2>${badge(o.status)}</div><p><strong>Necessidade:</strong> ${esc(o.description)}</p><p><strong>Atendimento:</strong> ${esc(modeNames[o.mode]||o.mode||'A combinar')}</p>${o.mode==='client'||o.requestedNeighborhood?`<p><strong>Local:</strong> ${esc(o.requestedNeighborhood||o.neighborhood)}</p>`:''}${o.preferred&&!o.booking?`<p><strong>Preferência:</strong> ${esc(o.preferred)}</p>`:''}${o.mediaIds?.length?`<div class="gallery">${o.mediaIds.map(mid=>`<img src="/media/${esc(mid)}" alt="Foto enviada no pedido">`).join('')}</div>`:''}${o.booking?`<p><strong>Agendado:</strong> ${date(o.booking.start)} até ${date(o.booking.end)}</p>`:''}${o.quote&&(provider||o.status!=='quoted')?`<p><strong>Combinado:</strong> ${esc(o.quote.scope)} · ${esc(o.quote.price)}</p>`:''}</div><div class="panel"><h2>Histórico</h2>${eventList(o.events)}</div>${chat}</div><div class="stack"><div class="action-box"><h2>Próxima ação</h2>${actions||'<p>Este pedido está encerrado. O histórico continua disponível.</p>'}</div><a class="button secondary" href="/servico/${o.listingId}">Ver anúncio</a></div></div>`)}
async function pageJobs(){const q=params().get('q')||'',area=params().get('area')||'',d=await api('/api/jobs'+location.search);show(heading('Vagas em Itarema','Encontre oportunidades perto de você',state.user?.activities?.includes('business')?'<a class="button secondary" href="/nova-vaga">+ Publicar vaga</a>':'')+`<form class="toolbar" data-form="job-search"><label class="search"><span>⌕</span><input name="q" aria-label="Buscar vaga" placeholder="Cargo ou área" value="${esc(q)}"></label><input class="field" name="area" placeholder="Bairro ou localidade" value="${esc(area)}"><button class="button primary">Buscar</button></form><p class="count">${d.jobs.length} ${d.jobs.length===1?'vaga encontrada':'vagas encontradas'}</p><div class="list">${d.jobs.length?d.jobs.map(j=>card('/vaga/'+j.id,j.title,`${j.companyName} · ${j.neighborhood} · ${j.contract||'Contrato a combinar'}`,`<span class="pill">${esc(j.salary||'A combinar')}</span>`)).join(''):empty('Nenhuma vaga encontrada','Tente outro cargo ou localidade.','/vagas','Limpar busca')}</div>`)}
async function pageJob(id){const j=(await api('/api/jobs/'+id)).job,own=j.isOwner;show(back('/vagas')+`<div class="two-col"><div class="stack"><div class="panel"><p class="eyebrow">Vaga · ${esc(j.neighborhood)}</p><h1>${esc(j.title)}</h1><p><a href="/perfil/${j.userId}" style="color:var(--blue);font-weight:700">${esc(j.companyName)}</a></p><div class="stat-row"><span class="stat">${esc(j.contract||'Contrato a combinar')}</span><span class="stat">${esc(j.schedule||'Jornada a combinar')}</span><span class="stat">${esc(jobModeNames[j.mode]||j.mode||'Presencial')}</span></div><h2>Sobre a vaga</h2><p class="detail-text">${esc(j.description)}</p>${j.requirements?`<h2>Requisitos</h2><p class="detail-text">${esc(j.requirements)}</p>`:''}<h2>Remuneração</h2><p>${esc(j.salary||'A combinar')}</p></div></div><div class="panel"><h2>Próximo passo</h2>${own?`<div class="stack"><a class="button primary" href="/minhas-vagas">Ver candidatos</a><a class="button secondary" href="/nova-vaga/${j.id}">Editar vaga</a>${j.status!=='closed'?`<form class="form" data-form="close-job" data-id="${j.id}"><label>Motivo do encerramento<select name="reason"><option>Contratação concluída</option><option>Processo encerrado</option></select></label><button class="button danger">Encerrar vaga</button></form>`:''}</div>`:j.applied?`<p>Você já se candidatou.</p><a class="button primary" href="/candidaturas">Acompanhar candidatura</a>`:`<p>Confira as informações e envie seu perfil à empresa.</p><a class="button primary" href="/candidatar/${j.id}">Candidatar-se</a>`}</div></div>`)}
async function pageJobForm(id){if(needLogin(location.pathname))return;let j={};if(id)j=(await api('/api/jobs/'+id)).job;show(back('/minhas-vagas')+heading(id?'Editar vaga':'Publicar vaga')+`<div class="panel"><form class="form" data-form="job" data-id="${id||''}"><div class="form-grid"><label>Cargo<input name="title" required value="${esc(j.title||'')}" placeholder="Ex.: Atendente"></label><label>Localidade<input name="neighborhood" required value="${esc(j.neighborhood||state.user.profile?.neighborhood||'')}" placeholder="Ex.: Centro"></label></div><label>Descrição da vaga<textarea name="description" required minlength="20" placeholder="Atividades e contexto do trabalho">${esc(j.description||'')}</textarea></label><label>Requisitos essenciais<textarea name="requirements" placeholder="O que a pessoa precisa saber ou ter">${esc(j.requirements||'')}</textarea></label><div class="form-grid"><label>Tipo de contrato<input name="contract" value="${esc(j.contract||'')}" placeholder="Ex.: CLT, temporário"></label><label>Jornada<input name="schedule" value="${esc(j.schedule||'')}" placeholder="Ex.: segunda a sábado"></label></div><div class="form-grid"><label>Formato<select name="mode"><option value="onsite">Presencial</option><option value="hybrid" ${j.mode==='hybrid'?'selected':''}>Híbrido</option><option value="remote" ${j.mode==='remote'?'selected':''}>Remoto</option></select></label><label>Remuneração<input name="salary" value="${esc(j.salary||'')}" placeholder="Ex.: R$ 1.600 ou A combinar"></label></div><div class="form-actions"><button class="button primary" name="status" value="open">Publicar vaga</button><button class="button secondary" name="status" value="draft">Salvar rascunho</button>${id?`<button class="button secondary" name="status" value="${j.status==='paused'?'open':'paused'}">${j.status==='paused'?'Retomar':'Pausar'}</button>`:''}</div></form></div>`)}
async function pageMyJobs(){
 if(needLogin('/minhas-vagas'))return;
 const [jobs,apps]=await Promise.all([api('/api/my-jobs'),api('/api/applications')]);
 const rows=jobs.jobs.map(j=>{const related=apps.applications.filter(a=>a.jobId===j.id),pending=related.filter(a=>applicationStep(a).group==='action').length;return `<article class="manage-card"><div><div class="manage-card-title"><h3>${esc(j.title)}</h3>${badge(j.status)}</div><p>${esc(j.neighborhood)} · ${related.length} ${related.length===1?'candidatura':'candidaturas'}</p><strong class="next-label">${pending?pending+' candidato'+(pending===1?' precisa':'s precisam')+' de resposta':'Nenhuma ação pendente'}</strong></div><div class="manage-card-actions"><a class="button ${pending?'primary':'secondary'} small" href="/candidaturas?vaga=${j.id}">Ver candidatos</a><a class="button secondary small" href="/nova-vaga/${j.id}">Editar vaga</a></div></article>`});
 show(heading('Minhas vagas','Vagas e candidatos no mesmo lugar','<a class="button primary" href="/nova-vaga">+ Nova vaga</a>')+(rows.length?`<div class="manage-list">${rows.join('')}</div>`:empty('Nenhuma vaga publicada','Publique uma vaga para receber candidaturas.','/nova-vaga','Publicar vaga')));
}
async function pageApply(id){if(needLogin(location.pathname))return;const j=(await api('/api/jobs/'+id)).job;show(back('/vaga/'+id)+heading('Candidatar-se',j.title)+`<div class="two-col"><div class="panel"><h2>O que a empresa receberá</h2><p><strong>${esc(state.user.name)}</strong> · ${esc(state.user.profile?.neighborhood||'Itarema')}</p><p><strong>Objetivo:</strong> ${esc(state.user.profile?.desiredWork||'Não informado')}</p><p><strong>Habilidades:</strong> ${esc(state.user.profile?.skills||'Não informadas')}</p><a href="/conta" class="button secondary small">Editar perfil</a><hr><form class="form" data-form="apply" data-id="${id}"><label>Apresentação <small>Opcional</small><textarea name="message" placeholder="Conte por que tem interesse na vaga"></textarea></label><button class="button primary">Enviar candidatura</button></form></div><div class="panel"><h3>${esc(j.companyName)}</h3><p>${esc(j.title)} · ${esc(j.neighborhood)}</p><p class="muted">Você poderá acompanhar cada etapa em Minhas candidaturas.</p></div></div>`)}
async function pageApplications(){
 if(needLogin('/candidaturas'))return;
 const d=await api('/api/applications'),business=state.user.role==='business',jobId=params().get('vaga'),own=d.applications.filter(a=>business?a.job?.userId===state.user.id:a.userId===state.user.id),rows=business&&jobId?own.filter(a=>a.jobId===jobId):own;
 const filter=business&&jobId?`<div class="filter-note">Candidatos desta vaga <a href="/candidaturas">Ver todos</a></div>`:'';
 const groups=[['action','Precisa de você'],['waiting','Aguardando resposta'],['progress','Entrevistas e conversas'],['closed','Encerradas']].map(([key,title])=>manageGroup(title,rows.filter(a=>applicationStep(a).group===key).map(applicationRow))).join('');
 show(heading(business?'Candidatos':'Minhas candidaturas','',business?'<a class="button secondary" href="/minhas-vagas">Minhas vagas</a>':'<a class="button secondary" href="/vagas">Buscar vagas</a>')+filter+(rows.length?groups:empty(business?'Nenhum candidato':'Nenhuma candidatura',business?'As candidaturas desta vaga aparecerão aqui.':'Encontre uma vaga e envie seu perfil.',business?'/minhas-vagas':'/vagas',business?'Ver vagas':'Buscar vagas')));
}
const appForm=(id,action,fields,label,style='primary')=>`<form class="form" data-form="application-action" data-id="${id}" data-action="${action}">${fields}<button class="button ${style}">${label}</button></form>`;
const jobOfferForm=(id,j)=>appForm(id,'offer',`<label>Remuneração<input name="salary" required placeholder="Ex.: R$ 1.600"></label><label>Jornada<input name="schedule" required placeholder="Ex.: segunda a sábado"></label><label>Data prevista de início<input name="start" type="date" required></label><label>Local de trabalho<input name="location" value="${esc(j.neighborhood||'')}"></label>`,'Enviar proposta','secondary');
async function pageApplication(id){if(needLogin(location.pathname))return;const a=(await api('/api/applications/'+id)).application,candidate=a.userId===state.user.id,employer=!candidate,chat=await chatBlock(a.chatId),j=a.job,step=applicationStep(a);let actions=step.group==='action'?'':`<p class="step-summary">${esc(step.group==='closed'?'Processo encerrado.':step.label)}</p>`;
 if(employer&&['received','sent','reviewing','in_conversation'].includes(a.status)){if(['received','sent'].includes(a.status))actions+=`<button class="button secondary" data-action="app-quick" data-id="${id}" data-value="review">Marcar em análise</button>`;actions+=optionalAction('Convidar para entrevista',appForm(id,'invite_interview',`<div class="form-grid"><label>Formato<select name="format"><option>Presencial</option><option>Vídeo</option><option>Telefone</option></select></label><label>Local ou link<input name="location" placeholder="Endereço ou link"></label></div><label>Entrevistador<input name="interviewer" placeholder="Nome de quem vai conversar"></label><div class="form-grid"><label>Início<input type="datetime-local" name="start" required></label><label>Fim<input type="datetime-local" name="end" required></label></div><label>Instruções <small>Opcional</small><input name="instructions" placeholder="O que a pessoa precisa saber"></label>`,'Enviar convite'));actions+=optionalAction('Enviar proposta de trabalho',jobOfferForm(id,j));actions+=optionalAction('Não selecionar',appForm(id,'reject','<label>Mensagem ao candidato<input name="detail" placeholder="Agradeça pela participação"></label>','Não selecionar','danger'))}
 if(employer&&a.status==='offer_pending'&&Date.parse(a.offer?.expiresAt||0)<Date.now())actions+=optionalAction('Renovar proposta',jobOfferForm(id,j));
 if(candidate&&a.status==='interview_pending'&&a.interview?.status==='pending')actions+=`<h3>Convite para entrevista</h3><p>${esc(a.interview.format)} · ${esc(a.interview.location)}</p>${a.interview.slots.map((s,i)=>`<button class="button secondary" data-action="interview-choice" data-id="${id}" data-index="${i}">Confirmar ${date(s.start)}</button>`).join(' ')}<button class="button danger" data-action="app-quick" data-id="${id}" data-value="interview_decline">Recusar convite</button>`;
 if(candidate&&a.interview?.status==='pending')actions+=optionalAction('Sugerir outro horário',appForm(id,'interview_respond','<input type="hidden" name="response" value="suggest"><div class="form-grid"><label>Início<input type="datetime-local" name="start" required></label><label>Fim<input type="datetime-local" name="end" required></label></div>','Sugerir horário','secondary'));
 if(a.interview?.status==='confirmed')actions+=`<div class="panel"><h3>Entrevista confirmada</h3><p>${date(a.interview.slot?.start)} · ${esc(a.interview.format)} · ${esc(a.interview.location)}</p>${employer?`<button class="button secondary" data-action="app-quick" data-id="${id}" data-value="interview_done">Marcar como realizada</button>`:''}</div>`+optionalAction('Pedir remarcação',appForm(id,'interview_reschedule','<div class="form-grid"><label>Novo início<input type="datetime-local" name="start" required></label><label>Novo fim<input type="datetime-local" name="end" required></label></div>','Pedir remarcação','secondary'));
 if(a.interview?.status==='suggested')actions+=`<p>Outro horário sugerido: ${date(a.interview.suggestion?.start)}</p>${a.interview.suggestion?.from!==state.user.id?`<button class="button primary" data-action="app-quick" data-id="${id}" data-value="interview_accept_suggestion">Aceitar novo horário</button>`:'<p class="muted">Aguardando resposta da outra parte.</p>'}`;
 if(a.interview&&(['confirmed','suggested'].includes(a.interview.status)||employer&&a.interview.status==='pending'))actions+=optionalAction('Cancelar entrevista',appForm(id,'interview_cancel','<label>Motivo<input name="detail" required minlength="3"></label>','Cancelar entrevista','danger'));
 if(candidate&&a.status==='offer_pending')actions+=`<div class="panel"><h3>Proposta de trabalho</h3><p><strong>${esc(a.offer.title)}</strong></p><p>${esc(a.offer.salary)} · ${esc(a.offer.schedule)} · início em ${calendarDay(a.offer.start)}</p>${Date.parse(a.offer.expiresAt)<Date.now()?'<p>O prazo desta proposta terminou. Aguarde uma nova proposta ou converse com a empresa.</p>':`<p class="muted">Responder até ${date(a.offer.expiresAt)}</p><button class="button primary" data-action="offer-choice" data-id="${id}" data-value="accept">Aceitar proposta</button> <button class="button secondary" data-action="offer-choice" data-id="${id}" data-value="decline">Recusar</button>`}</div>`;
 if(employer&&a.status==='offer_accepted')actions+=`<button class="button primary" data-action="app-quick" data-id="${id}" data-value="hire">Confirmar contratação</button>`;
 if(candidate&&!['hired','rejected','withdrawn','closed'].includes(a.status))actions+=optionalAction('Retirar candidatura',`<button class="button danger" data-action="app-quick" data-id="${id}" data-value="withdraw">Retirar candidatura</button>`);
 if(employer)actions+=optionalAction('Notas internas',`${a.notes?.length?a.notes.map(n=>`<p class="muted">${esc(n.text)} · ${date(n.createdAt)}</p>`).join(''):''}`+appForm(id,'note','<label>Nota para sua equipe<input name="detail" required minlength="2"></label>','Salvar nota','secondary'));
 show(back(employer?'/candidaturas?vaga='+j.id:'/candidaturas')+heading(j.title,candidate?j.companyName:a.candidate?.name||'Candidato')+`<div class="two-col"><div class="stack"><div class="panel"><div class="page-head"><h2>Candidatura</h2>${badge(a.status)}</div><p><strong>Enviada em:</strong> ${date(a.createdAt)}</p><p><strong>Apresentação:</strong> ${esc(a.message||'Sem apresentação adicional')}</p><p><strong>Habilidades:</strong> ${esc(a.snapshot?.skills||a.candidate?.skills||'Não informadas')}</p></div><div class="panel"><h2>Histórico</h2>${eventList(a.events)}</div>${chat}</div><div class="stack"><div class="action-box"><h2>Próxima ação</h2>${actions||'<p>Você pode acompanhar o histórico e as mensagens aqui.</p>'}</div>${employer?`<a class="button secondary" href="/perfil/${a.userId}">Ver perfil do candidato</a>`:''}<a class="button secondary" href="/vaga/${j.id}">Ver vaga</a></div></div>`)}
async function pageTalents(){const q=params().get('q')||'',d=await api('/api/talents?q='+encodeURIComponent(q));show(heading('Talentos em Itarema','Pessoas abertas a oportunidades')+`<form class="toolbar" data-form="talent-search"><label class="search"><span>⌕</span><input name="q" placeholder="Habilidade, cargo ou localidade" value="${esc(q)}"></label><button class="button primary">Buscar</button></form><div class="grid">${d.talents.length?d.talents.map(p=>`<a class="card talent-card" href="/perfil/${p.id}"><div class="card-body"><div class="profile-row"><span class="avatar">${avatar(p)}</span><div><h3>${esc(p.name)}</h3><small>${esc(p.neighborhood||'Itarema')}</small></div></div><p style="margin-top:15px"><strong>${esc(p.desiredWork||'Aberto a oportunidades')}</strong></p><p>${esc(p.skills||p.bio||'Ver perfil')}</p><span style="color:var(--blue);font-weight:700">Ver perfil →</span></div></a>`).join(''):empty('Nenhum perfil encontrado','Tente outra área ou habilidade.','/talentos','Limpar busca')}</div>`)}
async function pageProducts(){const q=params().get('q')||'',d=await api('/api/products?q='+encodeURIComponent(q));show(heading('Produtos locais','Veja o que os anunciantes oferecem',state.user?.activities?.some(x=>['professional','business'].includes(x))?'<a class="button secondary" href="/novo-produto">+ Anunciar produto</a>':'')+`<form class="toolbar" data-form="product-search"><label class="search"><span>⌕</span><input name="q" placeholder="Qual produto você procura?" value="${esc(q)}"></label><button class="button primary">Buscar</button></form><div class="grid">${d.products.length?d.products.map(x=>`<a class="card service-card" href="/produto/${x.id}"><div class="media-cover">${x.media?.[0]?mediaTile(x.media[0]):'<span class="placeholder">◇</span>'}</div><div class="card-body"><h3>${esc(x.title)}</h3><p>${esc(x.seller?.name)} · ${esc(x.neighborhood)}</p><div class="card-footer"><strong>${esc(x.price)}</strong><span>Ver produto →</span></div></div></a>`).join(''):empty('Nenhum produto encontrado','Tente outra busca.','/produtos','Limpar busca')}</div>`)}
async function pageProductForm(id){if(needLogin(location.pathname))return;let x={};if(id)x=(await api('/api/products/'+id)).product;show(back('/meus-produtos')+heading(id?'Editar produto':'Anunciar produto')+`<div class="panel"><form class="form" data-form="product" data-id="${id||''}"><label>Produto<input name="title" value="${esc(x.title||'')}" required placeholder="Ex.: bolo caseiro"></label><label>Descrição<textarea name="description" required minlength="10" placeholder="Detalhes importantes para quem compra">${esc(x.description||'')}</textarea></label><div class="form-grid"><label>Preço<input name="price" required value="${esc(x.price||'')}" placeholder="Ex.: R$ 35"></label><label>Localidade<input name="neighborhood" required value="${esc(x.neighborhood||state.user.profile?.neighborhood||'')}"></label></div><div class="form-grid"><label>Disponibilidade<input name="availability" value="${esc(x.availability||'')}" placeholder="Ex.: pronta entrega"></label><label>Retirada ou entrega<input name="delivery" value="${esc(x.delivery||'')}" placeholder="Como combinar"></label></div><label>Fotos e vídeos<input type="file" name="media" accept="image/jpeg,image/png,image/webp,video/mp4,video/webm" multiple></label><div class="form-actions"><button class="button primary" name="status" value="published">Salvar e publicar</button>${id?`<button class="button secondary" name="status" value="${x.status==='paused'?'published':'paused'}">${x.status==='paused'?'Retomar':'Pausar'}</button><button class="button danger" name="status" value="archived">Arquivar</button>`:''}</div></form></div>`)}
async function pageChats(){if(needLogin('/mensagens'))return;const d=await api('/api/chats');show(heading('Mensagens','Conversas ligadas aos seus pedidos e vagas')+`<div class="list">${d.chats.length?d.chats.map(c=>card('/mensagens/'+c.id,c.other?.name||'Conversa',`${c.contextType==='order'?'Pedido':c.contextType==='application'?'Candidatura':c.contextType==='service'?'Serviço':c.contextType==='product_order'?'Pedido de produto':c.contextType==='product'?'Produto':'Contato'} · ${esc(c.lastMessage?.text||'Comece a conversa')}`,`<small>${date(c.updatedAt)}</small>`)).join(''):empty('Nenhuma conversa','Quando você entrar em contato ou receber um pedido, a conversa aparecerá aqui.','/servicos','Buscar serviço')}</div>`)}
async function pageChat(id){if(needLogin(location.pathname))return;const c=(await api('/api/chats/'+id)).chat,context=c.contextType==='order'?'/pedidos/'+c.contextId:c.contextType==='application'?'/candidaturas/'+c.contextId:c.contextType==='service'?'/servico/'+c.contextId:c.contextType==='product_order'?'/pedidos-produtos/'+c.contextId:c.contextType==='product'?'/produto/'+c.contextId:'';show(back('/mensagens')+heading(c.other?.name||'Conversa')+`<div class="panel" style="max-width:780px">${context?`<a class="button secondary small" href="${context}">Ver ${c.contextType==='order'?'pedido':c.contextType==='application'?'candidatura':c.contextType==='product_order'?'pedido de produto':c.contextType==='product'?'produto':'serviço'} →</a>`:''}<div class="bubble-list" style="margin-top:15px">${c.messages.length?c.messages.map(m=>`<div class="bubble ${m.type==='system'?'system':m.userId===state.user.id?'mine':''}"><p>${esc(m.text)}</p><small>${date(m.createdAt)}</small></div>`).join(''):'<p class="muted">Envie a primeira mensagem.</p>'}</div><form class="compose" data-form="message" data-id="${c.id}"><input name="text" required placeholder="Escreva sua mensagem" aria-label="Mensagem"><button class="button primary">Enviar</button></form></div>`)}
async function pageNotices(){if(needLogin('/avisos'))return;const d=await api('/api/notifications');show(heading('Avisos',d.unread+' não lidos',d.unread?'<button class="button secondary" data-action="read-all">Marcar todos como lidos</button>':'')+`<div class="card">${d.notifications.length?d.notifications.map(n=>`<a href="${esc(n.href)}" data-notice="${n.id}" class="notice-row ${n.read?'':'unread'}">${esc(n.title)}<small>${date(n.createdAt)}</small></a>`).join(''):empty('Tudo em dia','Avisos sobre pedidos, vagas e mensagens aparecerão aqui.','/minha-area','Minha área')}</div>`)}
async function pageInvites(){if(needLogin('/convites'))return;const d=await api('/api/invites');show(heading('Convites para vagas')+`<div class="list">${d.invites.filter(x=>x.targetId===state.user.id).length?d.invites.filter(x=>x.targetId===state.user.id).map(x=>`<div class="panel"><h3>${esc(x.job?.title||'Vaga')}</h3><p>${esc(x.sender?.name||'Empresa')} · ${esc(x.job?.neighborhood||'Itarema')}</p><p>${esc(x.message||'Você recebeu um convite para se candidatar.')}</p><p>${badge(x.status)}</p><div class="form-actions"><a class="button secondary" href="/vaga/${x.jobId}">Ver vaga</a>${x.status==='pending'?`<button class="button primary" data-action="invite" data-id="${x.id}" data-value="accept">Tenho interesse</button><button class="button secondary" data-action="invite" data-id="${x.id}" data-value="decline">Recusar</button>`:''}</div></div>`).join(''):empty('Nenhum convite','Empresas podem convidar você para vagas quando seu perfil está visível em Talentos.','/vagas','Ver vagas')}</div>`)}
function pagePost(){if(needLogin('/publicar'))return;show(back('/perfil/'+state.user.id)+heading('Nova publicação')+`<div class="panel"><form class="form" data-form="post"><label>O que deseja compartilhar?<textarea name="text" required minlength="3" placeholder="Mostre um trabalho ou conte uma novidade"></textarea></label><label>Fotos e vídeos<input type="file" name="media" accept="image/jpeg,image/png,image/webp,video/mp4,video/webm" multiple></label><button class="button primary">Publicar</button></form></div>`)}
function pageReport(){if(needLogin(location.pathname+location.search))return;const type=params().get('tipo')||'profile',id=params().get('id')||'';show(back()+heading('Denunciar conteúdo')+`<div class="panel auth-layout"><p>Conte o que aconteceu. A denúncia não é mostrada à pessoa denunciada.</p><form class="form" data-form="report"><input type="hidden" name="targetType" value="${esc(type)}"><input type="hidden" name="targetId" value="${esc(id)}"><label>Motivo<textarea name="reason" minlength="5" required placeholder="Descreva o problema"></textarea></label><button class="button primary">Enviar denúncia</button></form></div>`)}
async function pageAdmin(){if(needLogin('/admin/denuncias'))return;const d=await api('/api/admin/reports');show(back('/minha-area')+heading('Denúncias','Área restrita de moderação')+`<div class="list">${d.reports.length?d.reports.map(r=>`<div class="panel"><div class="page-head"><h3>${esc(r.targetType)} · ${esc(r.targetId)}</h3>${badge(r.status)}</div><p>${esc(r.reason)}</p><small class="muted">${date(r.createdAt)}</small>${r.status==='open'?`<form class="form" data-form="resolve-report" data-id="${r.id}"><label>Decisão<input name="resolution" required placeholder="Explique a decisão"></label><label class="check"><input type="checkbox" name="pause"> Pausar anúncio ou vaga</label><button class="button primary">Registrar decisão</button></form>`:`<p class="muted">Decisão: ${esc(r.resolution||'Analisado')}</p>`}</div>`).join(''):empty('Nenhuma denúncia','As ocorrências aparecerão aqui.','/minha-area','Minha área')}</div>`)}
async function render(){const path=decodeURI(location.pathname);try{if(path==='/'||path==='/servicos')return pageServices();if(path==='/entrar')return authPage(false);if(path==='/cadastro')return authPage(true);if(path==='/minha-area')return pageDashboard();if(path==='/conta')return pageAccount();if(path==='/meus-servicos')return pageMyServices();if(path==='/anunciar')return pageServiceForm();if(path==='/solicitar')return go('/servicos');if(path==='/pedidos')return pageOrders();if(path==='/vagas')return pageJobs();if(path==='/produtos')return pageProductsHub();if(path==='/meus-produtos')return pageMyProducts();if(path==='/novo-produto')return pageProductForm();if(path==='/pedidos-produtos')return pageProductOrders();if(path==='/nova-vaga')return pageJobForm();if(path==='/minhas-vagas')return pageMyJobs();if(path==='/candidaturas')return pageApplications();if(path==='/talentos')return pageTalents();if(path==='/mensagens')return pageChats();if(path==='/avisos')return pageNotices();if(path==='/convites')return pageInvites();if(path==='/publicar')return pagePost();if(path==='/denunciar')return pageReport();if(path==='/admin/denuncias')return pageAdmin();let m;if(m=path.match(/^\/servico\/([^/]+)$/))return pageService(m[1]);if(m=path.match(/^\/perfil\/([^/]+)$/))return pageProfile(m[1]);if(m=path.match(/^\/anunciar\/([^/]+)$/))return pageServiceForm(m[1]);if(m=path.match(/^\/solicitar\/([^/]+)$/))return pageRequest(m[1]);if(m=path.match(/^\/pedidos\/([^/]+)$/))return pageOrder(m[1]);if(m=path.match(/^\/vaga\/([^/]+)$/))return pageJob(m[1]);if(m=path.match(/^\/produto\/([^/]+)$/))return pageProduct(m[1]);if(m=path.match(/^\/pedir-produto\/([^/]+)$/))return pageProductRequest(m[1]);if(m=path.match(/^\/pedidos-produtos\/([^/]+)$/))return pageProductOrder(m[1]);if(m=path.match(/^\/novo-produto\/([^/]+)$/))return pageProductForm(m[1]);if(m=path.match(/^\/nova-vaga\/([^/]+)$/))return pageJobForm(m[1]);if(m=path.match(/^\/candidatar\/([^/]+)$/))return pageApply(m[1]);if(m=path.match(/^\/candidaturas\/([^/]+)$/))return pageApplication(m[1]);if(m=path.match(/^\/mensagens\/([^/]+)$/))return pageChat(m[1]);if(m=path.match(/^\/convites\/([^/]+)$/))return pageInvites();show(heading('Página não encontrada')+empty('Esse endereço não existe','Volte para os serviços.','/servicos','Ver serviços'))}catch(e){show(back()+empty('Não foi possível carregar',e.message,location.pathname,'Tentar novamente'))}}
document.addEventListener('click',async e=>{const a=e.target.closest('a[href^="/"]');if(a&&!e.ctrlKey&&!e.metaKey&&!a.hasAttribute('download')){e.preventDefault();if(a.dataset.notice)post('/api/notifications/read',{id:a.dataset.notice}).catch(()=>{});go(a.getAttribute('href'));return}const b=e.target.closest('button[data-action]');if(!b)return;e.preventDefault();try{b.disabled=true;const action=b.dataset.action,id=b.dataset.id,v=b.dataset.value;if(action==='logout'){await post('/api/logout',{});state.user=null;go('/servicos','Você saiu da conta.')}else if(action==='availability'){const d=await put('/api/profile',{status:v});state.user=d.user;go('/conta','Disponibilidade atualizada.')}else if(action==='ready'){const d=await post('/api/ready',{ready:v==='1'});state.user=d.user;go('/conta','Estado atualizado.')}else if(action==='start-chat'){if(needLogin(b.dataset.product?'/produto/'+b.dataset.product:'/servico/'+(b.dataset.service||'')))return;const d=await post('/api/chats',{targetId:b.dataset.target,listingId:b.dataset.service,productId:b.dataset.product});go('/mensagens/'+d.chatId)}else if(action==='order-quick'){await post('/api/orders/'+id+'/action',{action:v});go('/pedidos/'+id,'Pedido atualizado.')}else if(action==='app-quick'){await post('/api/applications/'+id+'/action',{action:v==='interview_decline'?'interview_respond':v,...(v==='interview_decline'?{response:'decline'}:{})});go('/candidaturas/'+id,'Candidatura atualizada.')}else if(action==='interview-choice'){await post('/api/applications/'+id+'/action',{action:'interview_respond',response:'confirm',index:Number(b.dataset.index)});go('/candidaturas/'+id,'Entrevista confirmada.')}else if(action==='offer-choice'){await post('/api/applications/'+id+'/action',{action:'offer_respond',response:v});go('/candidaturas/'+id,'Resposta enviada.')}else if(action==='invite'){await post('/api/invites/'+id+'/respond',{accept:v==='accept'});go(v==='accept'?'/vaga/'+b.closest('.panel').querySelector('a[href^="/vaga/"]').getAttribute('href').split('/').at(-1):'/convites',v==='accept'?'Convite aceito. Agora você pode se candidatar.':'Convite recusado.')}else if(action==='read-all'){await post('/api/notifications/read',{});go('/avisos','Avisos marcados como lidos.')}}catch(error){b.disabled=false;state.flash=error.message;render()}});
document.addEventListener('submit',async e=>{const f=e.target.closest('form[data-form]');if(!f)return;e.preventDefault();const type=f.dataset.form,button=e.submitter||f.querySelector('button[type=submit],button:not([type])');if(button)button.disabled=true;try{let d,b=extract(f),id=f.dataset.id;
 if(type==='service-search'||type==='job-search'||type==='talent-search'||type==='product-search'){const q=new URLSearchParams();for(const [k,v] of Object.entries(b))if(v&&k!=='urgent')q.set(k,v);if(f.elements.urgent?.checked)q.set('urgent','1');go((type==='service-search'?'/servicos':type==='job-search'?'/vagas':type==='product-search'?'/produtos':'/talentos')+(q.toString()?'?'+q:''));return}
 if(type==='register'||type==='login'){d=await post('/api/'+type,{...b,role:b.role||'customer'});state.user=d.user;go(f.dataset.next||'/minha-area',type==='register'?'Conta criada.':'Você entrou na conta.');return}
 if(type==='profile'){const ids=await upload(f,'avatar'),covers=await upload(f,'cover');d=await put('/api/profile',{...b,serviceAreas:b.serviceAreas?.split(',').map(x=>x.trim()).filter(Boolean),talentVisible:f.elements.talentVisible?.checked,avatar:ids[0],cover:covers[0]});state.user=d.user;go('/conta','Perfil salvo.');return}
 if(type==='hours'){const hours=Array.from({length:7},(_,i)=>({enabled:!!f.elements['on'+i].checked,open:f.elements['open'+i].value,close:f.elements['close'+i].value}));d=await put('/api/profile',{hours});state.user=d.user;go('/conta','Horários salvos.');return}
 if(type==='service'){const fresh=await upload(f);let mediaIds=fresh;if(id&&!fresh.length){const old=(await api('/api/services/'+id)).service;mediaIds=old.mediaIds||[]}const modes=[...f.querySelectorAll('[name=modes]:checked')].map(x=>x.value);if(!modes.length){formError(f,'Escolha ao menos uma forma de atendimento.');if(button)button.disabled=false;return}const data={...b,modes,areas:b.areas?.split(',').map(x=>x.trim()).filter(Boolean),mediaIds,status:button?.value||'published'};d=id?await put('/api/services/'+id,data):await post('/api/services',data);go('/meus-servicos','Serviço salvo.');return}
 if(type==='product'){const fresh=await upload(f);let mediaIds=fresh;if(id&&!fresh.length)mediaIds=(await api('/api/products/'+id)).product.mediaIds||[];const data={...b,mediaIds,status:button?.value||'published'};d=id?await put('/api/products/'+id,data):await post('/api/products',data);go('/meus-produtos','Produto salvo.');return}
 if(type==='product-request'){d=await post('/api/product-orders',{productId:id,quantity:Number(b.quantity),method:b.method,neighborhood:b.neighborhood,note:b.note,preferredDate:b.preferredDate,preferredTime:b.preferredTime});go('/pedidos-produtos/'+d.order.id,'Pedido enviado ao vendedor.');return}
 if(type==='product-order-action'){await post('/api/product-orders/'+id+'/action',{action:f.dataset.action,...b});go('/pedidos-produtos/'+id,'Pedido atualizado.');return}
 if(type==='request'){const mediaIds=await upload(f);d=await post('/api/orders',{listingId:id,description:b.description,neighborhood:b.neighborhood,mode:b.mode,preferredDate:b.preferredDate,preferredTime:b.preferredTime,mediaIds});go('/pedidos/'+d.order.id,'Pedido enviado ao anunciante.');return}
 if(type==='order-action'){const data={action:f.dataset.action,...b};if(b.start)data.start=iso(b.start);if(b.end)data.end=iso(b.end);await post('/api/orders/'+id+'/action',data);go('/pedidos/'+id,'Pedido atualizado.');return}
 if(type==='review'){await post('/api/reviews',{orderId:id,stars:Number(b.stars),text:b.text});go('/pedidos/'+id,'Avaliação enviada.');return}
 if(type==='job'){const data={...b,status:button?.value||'open'};d=id?await put('/api/jobs/'+id,data):await post('/api/jobs',data);go('/minhas-vagas','Vaga salva.');return}
 if(type==='close-job'){await post('/api/jobs/'+id+'/close',{reason:b.reason});go('/minhas-vagas','Vaga encerrada e candidatos avisados.');return}
 if(type==='apply'){d=await post('/api/jobs/'+id+'/apply',{message:b.message});go('/candidaturas/'+d.application.id,'Candidatura enviada.');return}
 if(type==='application-action'){const data={action:f.dataset.action,...b};if(data.action==='invite_interview')data.slots=[{start:iso(b.start),end:iso(b.end)}];if(data.action==='interview_reschedule'||data.action==='interview_respond'&&data.response==='suggest'){data.start=iso(b.start);data.end=iso(b.end)}await post('/api/applications/'+id+'/action',data);go('/candidaturas/'+id,'Etapa atualizada.');return}
 if(type==='message'){await post('/api/chats/'+id,{text:b.text});render();return}
 if(type==='invite'){await post('/api/invites',{jobId:b.jobId,targetId:f.dataset.target,message:b.message});go('/perfil/'+f.dataset.target,'Convite enviado.');return}
 if(type==='resolve-report'){await post('/api/admin/reports/'+id+'/resolve',{resolution:b.resolution,pause:!!f.elements.pause.checked});go('/admin/denuncias','Decisão registrada.');return}
 if(type==='report'){await post('/api/reports',b);go('/minha-area','Denúncia enviada para análise.');return}
 if(type==='post'){const mediaIds=await upload(f);await post('/api/posts',{text:b.text,mediaIds});go('/perfil/'+state.user.id,'Publicação criada.');return}
 }catch(error){formError(f,error.message);if(button)button.disabled=false}});
document.addEventListener('change',e=>{if(e.target.name==='role')document.querySelectorAll('.role-option').forEach(option=>option.classList.toggle('selected',option.querySelector('input').checked));if(e.target.name==='mode'&&e.target.closest('form[data-form="request"]')){const label=e.target.form.querySelector('[data-client-location]'),client=e.target.value==='client';label.hidden=!client;label.querySelector('input').required=client}});
window.addEventListener('popstate',render);
document.addEventListener('change',e=>{if(e.target.name==='method'&&e.target.closest('form[data-form="product-request"]')){const label=e.target.form.querySelector('[data-delivery-location]'),delivery=e.target.value==='delivery';label.hidden=!delivery;label.querySelector('input').required=delivery}});

const productMethodNames={pickup:'Retirada',delivery:'Entrega',arrange:'A combinar'};
const productOrderStatus={new:'Aguardando vendedor',awaiting_buyer:'Aguardando comprador',quoted:'Valor confirmado',confirmed:'Pedido confirmado',handed_over:'Aguardando recebimento',completed:'Concluído',disputed:'Problema informado',declined:'Recusado',cancelled:'Cancelado'};
const productOrderStep=o=>{const seller=o.sellerId===state.user.id;if(['completed','declined','cancelled'].includes(o.status))return {group:'closed',label:'Ver histórico'};if(o.status==='new')return seller?{group:'action',label:'Responder pedido'}:{group:'waiting',label:'Aguardando vendedor'};if(o.status==='awaiting_buyer')return seller?{group:'waiting',label:'Aguardando resposta'}:{group:'action',label:'Responder vendedor'};if(o.status==='quoted')return seller?{group:'waiting',label:'Aguardando confirmação'}:{group:'action',label:'Confirmar ou ajustar'};if(o.status==='confirmed')return seller?{group:'action',label:'Acompanhar entrega ou retirada'}:{group:'progress',label:'Aguardando produto'};if(o.status==='handed_over')return seller?{group:'waiting',label:'Aguardando comprador'}:{group:'action',label:'Confirmar recebimento'};if(o.status==='disputed')return seller?{group:'progress',label:'Conversar sobre o problema'}:{group:'action',label:'Registrar solução'};return {group:'progress',label:'Acompanhar pedido'}};
const productOrderRow=o=>manageRow('/pedidos-produtos/'+o.id,o.productTitle+' · '+o.quantity+' un.',(o.sellerId===state.user.id?o.buyer?.name:o.seller?.name)+' · '+(productMethodNames[o.method]||'A combinar'),productOrderStep(o),productOrderStatus[o.status]||o.status);
const productActionForm=(id,action,fields,label,style='primary')=>`<form class="form" data-form="product-order-action" data-id="${id}" data-action="${action}">${fields}<button class="button ${style}">${label}</button></form>`;
async function pageProductRequest(id){
 if(needLogin(location.pathname))return;
 const x=(await api('/api/products/'+id)).product;
 if(x.isOwner)return go('/produto/'+id);
 show(back('/produto/'+id)+heading('Pedir produto',x.title)+`<div class="two-col"><div class="panel"><form class="form" data-form="product-request" data-id="${x.id}"><label>Quantidade<input name="quantity" type="number" min="1" max="99" value="1" required></label><label>Como quer receber?<select name="method"><option value="arrange">Combinar com o vendedor</option><option value="pickup">Retirar</option><option value="delivery">Receber por entrega</option></select></label><label data-delivery-location hidden>Bairro ou localidade da entrega<input name="neighborhood" placeholder="Ex.: Centro, Itarema" value="${esc(state.user.profile?.neighborhood||'')}"></label><label>Algum detalhe? <small>Opcional</small><textarea name="note" placeholder="Cor, tamanho ou outra informação importante"></textarea></label><details class="optional-details"><summary>Dia e horário preferidos (opcional)</summary><div class="optional-body form-grid"><label>Dia<input name="preferredDate" type="date"></label><label>Horário<input name="preferredTime" type="time"></label></div></details><button class="button primary">Enviar pedido</button></form></div><div class="panel"><h2>${esc(x.title)}</h2><p><strong>${esc(x.price)}</strong> · ${esc(x.neighborhood)}</p><p>O vendedor confirma a disponibilidade e o valor total. Você decide se aceita.</p></div></div>`);
}
async function pageProductOrders(){
 if(needLogin('/pedidos-produtos'))return;
 const all=(await api('/api/product-orders')).orders,received=all.filter(o=>o.sellerId===state.user.id),sent=all.filter(o=>o.buyerId===state.user.id),side=params().get('lado')||(state.user.role==='customer'?'feitos':'recebidos'),productId=params().get('produto'),source=side==='recebidos'?received:sent,rows=productId?source.filter(o=>o.productId===productId):source;
 const tabs=state.user.role==='customer'?'':`<nav class="tabs" aria-label="Pedidos de produtos"><a class="tab ${side==='recebidos'?'active':''}" href="/pedidos-produtos?lado=recebidos">Recebidos (${received.length})</a><a class="tab ${side==='feitos'?'active':''}" href="/pedidos-produtos?lado=feitos">Pedidos que fiz (${sent.length})</a></nav>`;
 const groups=[['action','Precisa de você'],['waiting','Aguardando resposta'],['progress','Em andamento'],['closed','Encerrados']].map(([key,title])=>manageGroup(title,rows.filter(o=>productOrderStep(o).group===key).map(productOrderRow))).join('');
 show(back('/produtos')+heading(side==='recebidos'?'Pedidos de produtos':'Minhas compras','',side==='recebidos'?'<a class="button secondary" href="/meus-produtos">Meus anúncios</a>':'')+tabs+(productId?`<div class="filter-note">Pedidos deste produto <a href="/pedidos-produtos?lado=recebidos">Ver todos</a></div>`:'')+(rows.length?groups:empty('Nenhum pedido de produto',side==='recebidos'?'Quando alguém pedir um produto, aparecerá aqui.':'Encontre um produto para fazer um pedido.','/produtos','Ver produtos')));
}
async function pageProductOrder(id){
 if(needLogin(location.pathname))return;
 const o=(await api('/api/product-orders/'+id)).order,seller=o.sellerId===state.user.id,chat=await chatBlock(o.chatId),step=productOrderStep(o);
 const form=(action,fields,label,style)=>productActionForm(id,action,fields,label,style);
 let actions='';
 if(seller&&o.status==='new')actions=`<h3>Confirmar disponibilidade e valor</h3>`+form('quote',`<label>Valor total<input name="price" required placeholder="Ex.: R$ 70 com entrega"></label><label>Como será a entrega ou retirada? <small>Opcional</small><textarea name="instructions" placeholder="Ponto de retirada, prazo ou taxa de entrega"></textarea></label><details class="optional-details"><summary>Combinar dia e horário (opcional)</summary><div class="optional-body form-grid"><label>Dia<input name="day" type="date"></label><label>Horário<input name="time" type="time"></label></div></details>`,'Enviar valor')+optionalAction('Pedir mais informações',form('ask','<label>Pergunta<input name="detail" required minlength="5"></label>','Enviar pergunta','secondary'))+optionalAction('Recusar pedido',form('decline','<label>Motivo<input name="detail" required minlength="3"></label>','Recusar','danger'));
 if(!seller&&o.status==='awaiting_buyer')actions=form('answer','<label>Sua resposta<textarea name="detail" required minlength="3"></textarea></label>','Responder');
 if(!seller&&o.status==='quoted')actions=`<div class="quote-highlight"><h3>Proposta do vendedor</h3><strong>${esc(o.quote.price)}</strong>${o.quote.instructions?`<p>${esc(o.quote.instructions)}</p>`:''}${o.quote.day?`<p>${calendarDay(o.quote.day)}${o.quote.time?' às '+esc(o.quote.time):''}</p>`:''}</div>`+form('accept','','Confirmar pedido')+optionalAction('Pedir ajuste',form('adjust','<label>O que deseja ajustar?<textarea name="detail" required minlength="5"></textarea></label>','Enviar ajuste','secondary'));
 if(seller&&o.status==='confirmed')actions=form('handover','','Marcar como entregue ou retirado');
 if(!seller&&o.status==='handed_over')actions=form('confirm','','Confirmar que recebi')+optionalAction('Não recebi ou houve problema',form('problem','<label>O que aconteceu?<textarea name="detail" required minlength="5"></textarea></label>','Informar problema','secondary'));
 if(!seller&&o.status==='confirmed')actions=optionalAction('Informar problema',form('problem','<label>O que aconteceu?<textarea name="detail" required minlength="5"></textarea></label>','Informar problema','secondary'));
 if(!seller&&o.status==='disputed')actions=form('resolve','<label>Como foi resolvido?<textarea name="detail" required minlength="3"></textarea></label>','Marcar como resolvido');
 if(!seller&&['new','awaiting_buyer','quoted','confirmed'].includes(o.status))actions+=optionalAction('Cancelar pedido',form('cancel','<label>Motivo <small>Opcional</small><input name="detail" placeholder="Se quiser, conte o motivo"></label>','Cancelar pedido','danger'));
 show(back('/pedidos-produtos?lado='+(seller?'recebidos':'feitos'))+heading(o.productTitle,productOrderStatus[o.status])+`<div class="two-col"><div class="stack"><div class="panel"><div class="page-head"><h2>Pedido #${esc(o.id.slice(0,8))}</h2><span class="pill">${esc(productOrderStatus[o.status])}</span></div><p><strong>${o.quantity} ${o.quantity===1?'unidade':'unidades'}</strong> · ${esc(productMethodNames[o.method])}</p>${o.neighborhood?`<p>Entrega em ${esc(o.neighborhood)}</p>`:''}${o.note?`<p>${esc(o.note)}</p>`:''}${o.preferredDate?`<p>Preferência: ${calendarDay(o.preferredDate)}${o.preferredTime?' às '+esc(o.preferredTime):''}</p>`:''}<a href="/produto/${o.productId}">Ver anúncio →</a></div><div class="panel"><h2>${esc(step.label)}</h2>${actions||`<p class="muted">${esc(step.group==='closed'?'Pedido encerrado.':'Acompanhe por aqui ou envie uma mensagem.')}</p>`}${o.quote&&o.status!=='quoted'?`<div class="quote-highlight"><strong>Valor combinado: ${esc(o.quote.price)}</strong>${o.quote.instructions?`<p>${esc(o.quote.instructions)}</p>`:''}${o.quote.day?`<p>${calendarDay(o.quote.day)}${o.quote.time?' às '+esc(o.quote.time):''}</p>`:''}</div>`:''}</div><div class="panel"><h2>Histórico</h2>${eventList(o.events)}</div></div><div class="stack"><div class="panel"><h2>${seller?'Comprador':'Vendedor'}</h2><a class="profile-row" href="/perfil/${seller?o.buyerId:o.sellerId}"><span class="avatar">${avatar(seller?o.buyer:o.seller)}</span><span><strong>${esc(seller?o.buyer?.name:o.seller?.name)}</strong></span></a><p class="muted">Pagamento combinado diretamente entre vocês.</p></div>${chat}</div></div>`);
}
