 const head=$('.page-head');
 if(head&&state.user){const links=document.createElement('div');links.className='form-actions';links.innerHTML=(state.user.role!=='customer'?'<a class="button secondary" href="/meus-produtos">Meus anúncios</a>':'')+'<a class="button secondary" href="/pedidos-produtos">Pedidos de produtos</a>';head.append(links)}
