async function pageProduct(id){
 const x=(await api('/api/products/'+id)).product;
 show(back('/produtos')+`<div class="two-col"><div class="stack">${x.media?.[0]?`<div class="detail-media">${mediaTile(x.media[0])}</div>`:''}${x.media?.length>1?`<div class="gallery">${x.media.slice(1).map(mediaTile).join('')}</div>`:''}<div class="panel"><h1>${esc(x.title)}</h1><p class="detail-text">${esc(x.description)}</p><h2>${esc(x.price)}</h2><p class="muted">${esc(x.availability)} · ${esc(x.delivery||'Combine retirada ou entrega com o vendedor')}</p></div></div><div class="panel"><a class="profile-row" href="/perfil/${x.seller.id}"><span class="avatar">${avatar(x.seller)}</span><span><strong>${esc(x.seller.name)}</strong><small>${esc(x.neighborhood)}</small></span></a><div class="stack" style="margin-top:20px">${x.isOwner?`<a class="button primary" href="/pedidos-produtos?lado=recebidos&produto=${x.id}">Ver pedidos</a><a class="button secondary" href="/novo-produto/${x.id}">Editar anúncio</a>`:`<a class="button primary" href="/pedir-produto/${x.id}">Pedir produto</a><button class="button secondary" data-action="start-chat" data-target="${x.seller.id}" data-product="${x.id}">Conversar</button>`}</div><p class="muted">O vendedor confirma o valor total antes de você aceitar.</p></div></div>`);
}
async function pageMyProducts(){
 if(needLogin('/meus-produtos'))return;
 const [d,requests]=await Promise.all([api('/api/my-products'),api('/api/product-orders')]);
 const rows=d.products.map(x=>{const related=requests.orders.filter(o=>o.productId===x.id&&o.sellerId===state.user.id),pending=related.filter(o=>productOrderStep(o).group==='action').length;return `<article class="manage-card"><div><div class="manage-card-title"><h3>${esc(x.title)}</h3>${badge(x.status)}</div><p>${esc(x.price)} · ${esc(x.neighborhood)}</p><strong class="next-label">${pending?pending+' pedido'+(pending===1?' precisa':'s precisam')+' de você':related.length+' pedido'+(related.length===1?'':'s')+' no total'}</strong></div><div class="manage-card-actions"><a class="button ${pending?'primary':'secondary'} small" href="/pedidos-produtos?lado=recebidos&produto=${x.id}">Ver pedidos</a><a class="button secondary small" href="/novo-produto/${x.id}">Editar anúncio</a></div></article>`});
 show(back('/produtos')+heading('Meus produtos','Anúncios e pedidos no mesmo lugar','<a class="button primary" href="/novo-produto">+ Novo produto</a>')+(rows.length?`<div class="manage-list">${rows.join('')}</div>`:empty('Seu primeiro produto','Mostre o que você vende em Itarema.','/novo-produto','Anunciar produto')));
}
render();
